+uint32_t getGroupZeroMask(unsigned varyingIdBits) {
+  assert(varyingIdBits < 32);
+  uint32_t pattern = 1;
+  for (unsigned stride = 1; stride <= varyingIdBits; stride <<= 1)
+    if (varyingIdBits & stride)
+      pattern |= pattern << stride;
+  return pattern;
