+  tt.func public @hoist_out_of_else(%cond: i1, %init: tensor<128x128xf32, #blocked>) -> tensor<128x128xf32, #blocked> {
+    // POST-PIPELINE: %[[A:.+]], %[[T0:.+]] = ttng.tmem_alloc : ()
