+    // POST-PIPELINE-NEXT: %[[T2:.+]] = "write_to_tmem"(%[[A]], %[[T1]])
+    // POST-PIPELINE-NEXT: scf.yield %[[T2]]
+    // POST-PIPELINE: %[[L:.+]], %{{.*}} = ttng.tmem_load %[[A]][%[[I]]]
